from fastapi import FastAPI, BackgroundTasks, Depends
from fastapi.responses import StreamingResponse
from models import Notification, TaskResult
from deps import get_async_db
from tasks import send_notification
from streaming import number_generator

app = FastAPI()


@app.get("/items")
async def list_items(db: dict = Depends(get_async_db)):
    return db["items"]


@app.post("/notify", response_model=TaskResult)
def create_notification(
    notification: Notification, background_tasks: BackgroundTasks
):
    background_tasks.add_task(
        send_notification, notification.email, notification.message
    )
    return TaskResult(status="queued", message=f"Notification queued for {notification.email}")


@app.get("/stream/{count}")
def stream_numbers(count: int):
    return StreamingResponse(number_generator(count), media_type="text/plain")


@app.get("/compute")
async def compute():
    result = await async_compute()
    return {"result": result}


